/**
 * VoiceIsolate Pro — Landing hero sculpture motion (Layer 4: Presentation)
 *
 * The sculpture itself is static SVG in `public/index.html` (generated by
 * scripts/generate-hero-sculpture.mjs); that markup is the prerendered still.
 * This module adds the Signal Glass drift: two compositor transforms per
 * frame (body 2 px, dust 6 px), driven by requestAnimationFrame, paused while
 * the tab is hidden or the hero is offscreen. When the motion policy allows
 * animation and WebGL2 exists, it then lazy-loads the 3D render
 * (HeroSculpture3D.js + vendored Three.js), which takes over after its first
 * frame; any failure or context loss hands the picture back to the SVG.
 * It never reads or touches audio.
 */
'use strict';

import { detectPerformanceTier } from '../core/PerformanceTier.js';
import { HERO_DRIFT, heroDriftOffset, selectHeroMotion, selectHeroRenderer } from '../core/HeroMotionPolicy.js';

const SOFTWARE_GL = /swiftshader|llvmpipe|softpipe|software|basic render|microsoft basic/i;

/**
 * WebGL2 capability probe. The probe context is released at once.
 * @returns {{ webgl2: boolean, software: boolean, renderer: string }}
 */
export function probeWebGL2(win) {
  try {
    const c = win.document.createElement('canvas');
    const gl = c.getContext?.('webgl2', { failIfMajorPerformanceCaveat: true });
    if (!gl) return { webgl2: false, software: false, renderer: '' };
    const info = gl.getExtension('WEBGL_debug_renderer_info');
    const renderer = String((info && gl.getParameter(info.UNMASKED_RENDERER_WEBGL)) || gl.getParameter(gl.RENDERER) || '');
    gl.getExtension('WEBGL_lose_context')?.loseContext();
    return { webgl2: true, software: SOFTWARE_GL.test(renderer), renderer };
  } catch {
    return { webgl2: false, software: false, renderer: '' };
  }
}

/** Live capability signals, read with the same guards as shouldLoadHeroVideo. */
function readMotionSignals(win) {
  const s = { reducedMotion: false, saveData: false, effectiveType: undefined, onLine: true };
  try {
    s.reducedMotion = !!win.matchMedia?.('(prefers-reduced-motion: reduce)').matches;
    const conn = win.navigator?.connection;
    s.saveData = conn?.saveData === true;
    s.effectiveType = typeof conn?.effectiveType === 'string' ? conn.effectiveType : undefined;
    s.onLine = win.navigator?.onLine !== false;
  } catch { /* capability probe only: default to the drift */ }
  return s;
}

/**
 * @param {HTMLElement} stage  `.v3-sculpture` element
 * @param {object} [opts]
 * @param {Window} [opts.win]
 * @param {(win: Window) => { webgl2: boolean, software: boolean }} [opts.webgl2]  WebGL2 probe (injectable for tests)
 * @param {() => Promise<{ mountHeroSculpture3D: Function }>} [opts.load3D]  lazy loader for the 3D render
 * @returns {{ policy: object, budget: object, ready: Promise<string>, stop: () => void }}
 */
export function mountHeroSculpture(stage, { win = window, webgl2 = probeWebGL2, load3D = () => import('./HeroSculpture3D.js') } = {}) {
  const doc = win.document;
  const tier = detectPerformanceTier(win);
  const policy = selectHeroMotion({ ...readMotionSignals(win), tier });
  stage.dataset.tier = tier;
  stage.dataset.motion = policy.motion;
  stage.dataset.render = 'svg';
  const width = win.innerWidth || 0;
  const gpu = policy.motion === 'drift' ? webgl2(win) : { webgl2: false, software: false };
  const budget = selectHeroRenderer(policy, { webgl2: gpu.webgl2 === true, software: gpu.software === true, viewportWidth: width });
  stage.dataset.renderReason = budget.reason;

  const body = stage.querySelector('.v3-sculpture__layer--body');
  const dust = stage.querySelector('.v3-sculpture__layer--dust');
  if (policy.motion !== 'drift' || !body || !dust || typeof win.requestAnimationFrame !== 'function') {
    return { policy, budget, ready: Promise.resolve('svg'), stop() {} };
  }

  const minFrameMs = policy.fps > 0 ? 1000 / policy.fps - 1 : 0;
  let raf = 0, last = -Infinity, onScreen = true, stopped = false;
  let clockOffset = 0, pausedAt = 0;

  let svgDrift = true, gl = null;
  const paint = (now) => {
    raf = 0;
    if (stopped || !svgDrift || doc.hidden || !onScreen) return;
    raf = win.requestAnimationFrame(paint);
    if (now - last < minFrameMs) return;
    last = now;
    const { x, y } = heroDriftOffset(now - clockOffset);
    body.style.transform = `translate3d(${(x * HERO_DRIFT.bodyPx).toFixed(2)}px, ${(y * HERO_DRIFT.bodyPx).toFixed(2)}px, 0)`;
    dust.style.transform = `translate3d(${(x * HERO_DRIFT.dustPx).toFixed(2)}px, ${(y * HERO_DRIFT.dustPx).toFixed(2)}px, 0)`;
  };
  const resume = () => {
    if (stopped || !svgDrift || raf || doc.hidden || !onScreen) return;
    // Continue the drift from where it paused instead of jumping ahead.
    if (pausedAt) { clockOffset += win.performance.now() - pausedAt; pausedAt = 0; }
    raf = win.requestAnimationFrame(paint);
  };
  const pause = () => {
    if (raf) { win.cancelAnimationFrame(raf); raf = 0; }
    if (!pausedAt) pausedAt = win.performance.now();
  };
  const sync = () => (doc.hidden || !onScreen ? pause() : resume());

  const io = typeof win.IntersectionObserver === 'function'
    ? new win.IntersectionObserver(([e]) => { onScreen = e.isIntersecting; sync(); })
    : null;
  io?.observe(stage);
  doc.addEventListener('visibilitychange', sync);

  // A visitor who turns on reduced motion mid-visit gets the still immediately.
  const reduceMq = win.matchMedia?.('(prefers-reduced-motion: reduce)');
  const onReduce = (e) => { if (e.matches) stop(); };

  const stop = () => {
    stopped = true;
    pause();
    gl?.stop();
    gl = null;
    stage.dataset.render = 'svg';
    io?.disconnect();
    doc.removeEventListener('visibilitychange', sync);
    reduceMq?.removeEventListener?.('change', onReduce);
    body.style.transform = '';
    dust.style.transform = '';
    stage.dataset.motion = 'still';
  };

  reduceMq?.addEventListener?.('change', onReduce);

  resume();

  // 3D takes over from the SVG drift once its first frame is up; the SVG keeps
  // drifting meanwhile, and gets the picture back on any failure.
  const fallBack = (reason, err) => {
    gl = null;
    stage.dataset.render = 'svg';
    if (stopped) return;
    console.warn(`[VIP][v3] 3D hero off (${reason}); SVG sculpture continues`, err || '');
    svgDrift = true;
    resume();
  };
  const ready = budget.renderer !== '3d'
    ? Promise.resolve('svg')
    : load3D()
      .then(({ mountHeroSculpture3D }) => (stopped ? null : mountHeroSculpture3D(stage, { win, budget, onFail: fallBack })))
      .then((handle) => {
        if (!handle) return 'svg';
        if (stopped) { handle.stop(); return 'svg'; }
        gl = handle;
        svgDrift = false;
        pause();
        body.style.transform = '';
        dust.style.transform = '';
        return '3d';
      })
      .catch((err) => { fallBack('load', err); return 'svg'; });

  return { policy, budget, ready, stop, stats: () => gl?.stats() };
}
